function drawBullets(){for(const b of shots){ctx.fillStyle='#ffe18b';ctx.shadowColor='#f2b84f';ctx.shadowBlur=9;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,7);ctx.fill()}ctx.shadowBlur=0;for(const b of foeShots){ctx.fillStyle='#ec8261';ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,7);ctx.fill()}}
