function drawParticles(){for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()}ctx.globalAlpha=1}
function drawHUD(){rr(78,105,844,52,13,'#1c211ddd','#58543d');text('HP',96,131,9,'#b7ac8e','left',900);for(let i=0;i<player.maxHp;i++){ctx.fillStyle=i<player.hp?'#e77c5e':'#53483c';ctx.beginPath();ctx.arc(128+i*21,131,7,0,7);ctx.fill();ctx.fillStyle=i<player.hp?'#f4b27c':'#71604c';ctx.beginPath();ctx.arc(128+i*21,129,4,0,7);ctx.fill()}
 text('ROOM',270,124,8,'#a69b7c','left',900);text(`${String(room).padStart(2,'0')} / 04`,270,139,13,'#f1e4c5','left',900);text('SCRAP',370,124,8,'#a69b7c','left',900);text(String(runStats.kills).padStart(2,'0'),370,139,13,'#f1e4c5','left',900);
 let shown=player.items.slice(-3);text('JUNK LOADOUT',490,124,8,'#a69b7c','left',900);if(shown.length)text(shown.map(x=>x.split(' ')[0]).join(' · '),490,139,10,'#b5d3a2','left',800);else text('nothing but grit',490,139,10,'#827c65','left',600);
 text(room===maxRooms?'BOSS ROOM':'CLEAR THE ROOM',892,131,9,room===maxRooms?'#e9ad67':'#c8d1ad','right',900);
 const boss=enemies.find(e=>e.type==='boss');if(boss){rr(365,624,270,12,6,'#1d211c','#756248');rr(368,627,264*(boss.hp/boss.maxHp),6,4,'#ce704d');text('THE LANDFILL KING',500,613,8,'#e6c690','center',900)}
 if(toastTime>0){ctx.globalAlpha=Math.min(1,toastTime*2);rr(278,173,444,34,11,'#1c211ee8','#5f5a43');text(toast,500,190,10,'#f2dfb6','center',900);ctx.globalAlpha=1}
}
function drawTitle(){ctx.fillStyle='#171b17b8';ctx.fillRect(0,0,W,H); // spotlight
 const grad=ctx.createRadialGradient(500,340,50,500,350,490);grad.addColorStop(0,'#1d211922');grad.addColorStop(1,'#11150edb');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
 // illustrated raccoon mugshot
 ctx.save();ctx.translate(500,252);ctx.rotate(-.08);ctx.fillStyle='#5e594a';ctx.beginPath();ctx.ellipse(0,0,78,79,0,0,7);ctx.fill();ctx.fillStyle='#aaa082';ctx.beginPath();ctx.ellipse(0,16,64,56,0,0,7);ctx.fill();ctx.fillStyle='#272720';ctx.beginPath();ctx.ellipse(-28,-1,35,20,-.13,0,7);ctx.ellipse(28,-1,35,20,.13,0,7);ctx.fill();ctx.fillStyle='#fff0cc';ctx.beginPath();ctx.arc(-25,-4,8,0,7);ctx.arc(25,-4,8,0,7);ctx.fill();ctx.fillStyle='#25251e';ctx.beginPath();ctx.arc(-23,-4,3,0,7);ctx.arc(27,-4,3,0,7);ctx.fill();ctx.fillStyle='#5b5141';ctx.beginPath();ctx.moveTo(-62,-45);ctx.lineTo(-69,-103);ctx.lineTo(-27,-69);ctx.fill();ctx.beginPath();ctx.moveTo(62,-45);ctx.lineTo(72,-97);ctx.lineTo(30,-68);ctx.fill();ctx.fillStyle='#df8150';ctx.beginPath();ctx.moveTo(-20,47);ctx.lineTo(28,47);ctx.lineTo(9,65);ctx.closePath();ctx.fill();ctx.fillStyle='#dfb66a';ctx.fillRect(-54,-93,15,7);ctx.fillRect(42,-88,15,7);ctx.restore();
 text('THE ALLEY IS',500,369,13,'#b9b08d','center',900);text('YOUR OYSTER.',500,400,34,'#f2e7cb','center',1000);text('A raccoon. A busted blaster. One very bad neighborhood.',500,435,12,'#b7ad92','center',600);
 rr(366,478,268,55,15,'#d58a45','#f4bd6f');text('▶   START THE RUN',500,505,14,'#28271f','center',1000);text('4 rooms · dumpster-born upgrades · one landfill king',500,561,10,'#b7ad92','center',700);text('Collect weird junk. Clear the nest. Get out with your snacks.',500,581,10,'#8e9075','center',600);
 text('DESKTOP  WASD move · mouse aim / fire   |   MOBILE  left thumb move · right thumb aim + fire',500,631,9,'#a9a185','center',700);
}
function drawEnd(win){ctx.fillStyle='#11150ee0';ctx.fillRect(0,0,W,H);text(win?'YOU OWN THE GUTTER.':'THE GUTTER WINS THIS ROUND.',500,272,29,win?'#eac879':'#e88967','center',1000);text(win?'The Landfill King has been thoroughly recycled.':'Your snack run ends in the trash. Every legend starts somewhere.',500,319,12,'#d2c7a6','center',600);text(`ROOMS CLEARED  ${win?'04':'0'+Math.max(1,room-1)}     ·     SCRAP CREATURES  ${runStats.kills}     ·     JUNK SCOOPED  ${player.items.length}`,500,365,11,'#b5d1a1','center',800);rr(385,420,230,51,13,'#d58a45','#f4bd6f');text('↻   RUN IT BACK',500,445,13,'#28271f','center',1000);text('TAP / CLICK OR PRESS ENTER',500,501,9,'#a9a185','center',800)}
function drawSticks(){if(!('ontouchstart'in window)&&navigator.maxTouchPoints<1)return;for(const [id,t] of touches){const isMove=id===sticks.move?.id,base=t.base,dx=t.dx||0,dy=t.dy||0;ctx.globalAlpha=.32;ctx.fillStyle='#d5c89c';ctx.beginPath();ctx.arc(base.x,base.y,46,0,7);ctx.fill();ctx.globalAlpha=.62;ctx.fillStyle='#f0d48b';ctx.beginPath();ctx.arc(base.x+dx*35,base.y+dy*35,19,0,7);ctx.fill()}ctx.globalAlpha=1}
function render(){ctx.setTransform(scale,0,0,scale,ox,oy);ctx.clearRect(0,0,canvas.width/scale,canvas.height/scale);ctx.save();if(shake)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawBackground();if(state==='play'){drawDoor();drawLootAll();drawBullets();enemies.forEach(drawEnemy);drawParticles();drawPlayer();drawHUD();drawSticks()}else if(state==='title')drawTitle();else drawEnd(state==='win');ctx.restore()}
function drawLootAll(){loot.forEach(drawLoot)}

